// Verify HMAC-SHA256 of the raw body against the shared secret.
const crypto = require('crypto');
const secret = $env.YEMEN_DISPATCH_SECRET;
const raw = $input.first().json.body ?? JSON.stringify($input.first().json);
const sig = $input.first().headers['x-signature'];
const expected = crypto.createHmac('sha256', secret).update(typeof raw === 'string' ? raw : JSON.stringify(raw)).digest('hex');
if (sig !== expected) { throw new Error('bad signature'); }
return [{ json: typeof raw === 'string' ? JSON.parse(raw) : raw }];

// Build the WhatsApp message text from the platform payload.
const p = $json;
const lines = [
  `🛠️ طلب جديد ${p.order.reference}`,
  `المحافظة: ${p.geo.governorate_name} - ${p.geo.district ?? ''}`,
  `الإجمالي التقديري: ${p.order.total_estimate} ${p.order.currency}`,
  '',
  `قبول: ${p.callbacks.accept}`,
  `رفض: ${p.callbacks.decline}`
];
return [{ json: { ...p, waText: lines.join('\n') } }];
